const raw = $input.first().json.body ?? $input.first().json;
const required = ['name', 'email', 'requested_service'];
const missing = required.filter((key) => !String(raw[key] ?? '').trim());
const email = String(raw.email ?? '').trim();
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const record = {
  lead_id: `AX-${Date.now()}`,
  name: String(raw.name ?? '').trim(),
  email,
  company: String(raw.company ?? '').trim(),
  requested_service: String(raw.requested_service ?? '').trim(),
  message: String(raw.message ?? '').trim(),
  source: String(raw.source ?? 'website_or_manual').trim(),
  received_at: new Date().toISOString(),
  status: 'NEW',
  approval_required_before_contact: true
};
const errors = [...missing.map((key) => `Missing ${key}`)];
if (email && !validEmail) errors.push('Invalid email format');
return [{ json: { ok: errors.length === 0, errors, lead: record, next_step: 'Review the enquiry and record it in the lead tracker. No email is sent by this workflow.' } }];
